p, k = map(int, input().split())

mod = 10**9 + 7
ans = 1
vis = [0] * (1 << 20)

def solve():
    global ans, vis, p, k
    ans = 1
    if k == 0:
        for i in range(1, p):
            ans = (ans * p) % mod
    elif k == 1:
        for i in range(1, p + 1):
            ans = (ans * p) % mod
    else:
        for i in range(p):
            if not vis[i]:
                length = 0
                current = i
                while not vis[current]:
                    vis[current] = 1
                    length += 1
                    current = (current * k) % p
                if current != 0:
                    ans = (ans * p) % mod
    return ans

print(solve())

